// ─────────────────────────────────────────────────────────────
//  SET 2 coding questions: statements, starter code, hidden drivers.
//  Test cases live in set2-tests.js (generated by tools/make-tests.mjs).
//
//  How a run works: the candidate writes class Solution. The page adds a
//  hidden driver that reads the test inputs, calls the method, and prints
//    @@B i          before test i
//    @@R i <value>  the returned value (compared to `expected`)
//    @@E i <msg>    an exception
//  Everything runs in the browser (see public/runner/runner.js).
// ─────────────────────────────────────────────────────────────
import { TESTS } from "./set2-tests.js";

// ── shared driver pieces ──
const PY_PRELUDE = `from typing import *
import sys, math, string, re, collections, heapq, bisect, itertools, functools
from collections import defaultdict, deque, Counter, OrderedDict
from functools import lru_cache, cache, reduce
from heapq import heappush, heappop, heapify
from bisect import bisect_left, bisect_right
import traceback as _dr_tb
sys.setrecursionlimit(5000)

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def _dr_fmt(e):
    line = None
    for fr in _dr_tb.extract_tb(e.__traceback__):
        if fr.filename == "solution.py":
            line = fr.lineno
    msg = f"{type(e).__name__}: {e}" if str(e) else type(e).__name__
    return msg.replace("\\n", " ") + (f" (line {line})" if line else "")

def _dr_build(vals):
    head = cur = ListNode()
    for v in vals:
        cur.next = ListNode(v)
        cur = cur.next
    return head.next

def _dr_show(node):
    out = []
    while node is not None and len(out) <= 1000:
        out.append(str(node.val))
        node = node.next
    if len(out) > 1000:
        return "[...too long, or the list has a cycle]"
    return "[" + ",".join(out) + "]"
`;

const PY_LOOP = (readCase, call) => `def _dr_main():
    toks = _dr_input.split()
    p = 0
    T = int(toks[p]); p += 1
    for i in range(T):
${readCase}
        print(f"\\n@@B {i}")
        try:
            r = ${call}
            print(f"\\n@@R {i} {r}")
        except BaseException as e:
            print(f"\\n@@E {i} {_dr_fmt(e)}")
_dr_main()
`;

const JAVA_DRV = `import java.io.*;
import java.util.*;

class TimeLimit extends Error {
    TimeLimit() { super("Time limit exceeded"); }
}

class Drv {
    // Loops in Solution.java call tick() (inserted by the runner) so an endless loop can't freeze the page.
    static long deadline = Long.MAX_VALUE;
    static int count = 0;
    static boolean tick() {
        if ((++count & 4095) == 0 && System.currentTimeMillis() > deadline) {
            deadline = Long.MAX_VALUE;
            throw new TimeLimit();
        }
        return true;
    }
    static String[] tokens(String path) throws IOException {
        InputStream in = new FileInputStream(path);
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        byte[] b = new byte[65536];
        int n;
        while ((n = in.read(b)) > 0) buf.write(b, 0, n);
        in.close();
        return new String(buf.toByteArray(), "UTF-8").trim().split("\\\\s+");
    }
    static String err(Throwable e) {
        int line = -1;
        for (StackTraceElement s : e.getStackTrace())
            if ("Solution.java".equals(s.getFileName())) { line = s.getLineNumber(); break; }
        if (e instanceof TimeLimit) return "Time limit exceeded";
        String m = e.getClass().getSimpleName() + (e.getMessage() != null ? ": " + e.getMessage() : "");
        return m.replace('\\n', ' ') + (line > 0 ? " (line " + line + ")" : "");
    }
}
`;

const JAVA_LISTNODE = `
class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

class Lists {
    static ListNode build(int[] v) {
        ListNode head = new ListNode(), cur = head;
        for (int x : v) { cur.next = new ListNode(x); cur = cur.next; }
        return head.next;
    }
    static String show(ListNode h) {
        StringBuilder sb = new StringBuilder("[");
        int c = 0;
        while (h != null && c <= 1000) { if (c > 0) sb.append(','); sb.append(h.val); h = h.next; c++; }
        if (c > 1000) return "[...too long, or the list has a cycle]";
        return sb.append(']').toString();
    }
}
`;

const JAVA_MAIN = (readCase, call) => `class Main {
    public static void main(String[] args) throws Exception {
        String[] t = Drv.tokens(args[0]);
        int p = 0;
        int T = Integer.parseInt(t[p++]);
        for (int i = 0; i < T; i++) {
${readCase}
            System.out.println("\\n@@B " + i);
            Drv.deadline = System.currentTimeMillis() + 5000;
            try {
                ${call}
                Drv.deadline = Long.MAX_VALUE;
            } catch (Throwable e) {
                Drv.deadline = Long.MAX_VALUE;
                System.out.println("\\n@@E " + i + " " + Drv.err(e));
            }
        }
        System.out.flush();
    }
}
`;

const CPP_LISTNODE = `struct ListNode {
    int val;
    ListNode *next;
    ListNode() : val(0), next(nullptr) {}
    ListNode(int x) : val(x), next(nullptr) {}
    ListNode(int x, ListNode *next) : val(x), next(next) {}
};`;

const CPP_MAIN = (helpers, readCase, call) => `${helpers}
int main() {
    int T;
    if (!(cin >> T)) return 0;
    for (int i = 0; i < T; i++) {
${readCase}
        cout << "\\n@@B " << i << endl;
        Solution dr_sol;
        ${call}
    }
    return 0;
}
`;

